package com.nsu.mspagent;

import android.app.*; import android.os.Bundle; import android.widget.*; import org.json.*;
public class KnowledgeActivity extends Activity {
    private LinearLayout p; private KnowledgeStore store; private TextView list;
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new KnowledgeStore(this);p=Ui.page(this,"Local Knowledge");p.addView(Ui.text(this,"Add short MSP runbook facts or answers. Matching keywords are injected into chat locally before the LLM request."));EditText title=Ui.input(this,"Title");EditText keys=Ui.input(this,"Keywords, comma separated");EditText body=Ui.input(this,"Knowledge / answer");body.setSingleLine(false);body.setMinLines(4);p.addView(title);p.addView(keys);p.addView(body);Button add=Ui.button(this,"Add Knowledge");add.setOnClickListener(v->{if(!title.getText().toString().trim().isEmpty()&&!body.getText().toString().trim().isEmpty()){store.add(title.getText().toString(),keys.getText().toString(),body.getText().toString());title.setText("");keys.setText("");body.setText("");refresh();}});p.addView(add);Button clear=Ui.button(this,"Clear Custom Knowledge");clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Clear custom knowledge?").setNegativeButton("Cancel",null).setPositiveButton("Clear",(d,w)->{store.clear();refresh();}).show());p.addView(clear);list=Ui.text(this,"");list.setTextIsSelectable(true);p.addView(list);refresh();setContentView(Ui.scroll(this,p));}
    private void refresh(){JSONArray a=store.all();StringBuilder s=new StringBuilder("\nStored entries: ").append(a.length()).append("\n");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)s.append("• ").append(x.optString("title")).append(" [").append(x.optString("keywords")).append("]\n");}list.setText(s.toString());}
}
